from __future__ import annotations

"""Domain models for Stripe balance transactions feeding a payout export.

A balance transaction is the canonical record Stripe emits for anything that
moves money on a connected account: a charge, a refund, a fee, an adjustment.
Each one carries a gross ``amount`` and a ``fee`` in integer cents, both in the
transaction's own currency. The finance export reads these rows and rolls the
ones attached to a single payout up into a reconciliation line.
"""

from dataclasses import dataclass, field


SUPPORTED_TYPES = {
    "charge",
    "payment",
    "refund",
    "payment_refund",
    "adjustment",
    "stripe_fee",
    "application_fee",
}

# Types whose gross amount is a credit to the account (money coming in).
# Refunds and most adjustments are debits and arrive with a negative amount.
CREDIT_TYPES = {"charge", "payment", "application_fee"}


def _clean(label: str, value: str | None) -> str:
    if value is None or not str(value).strip():
        raise ValueError(f"{label} is required")
    return str(value).strip()


def _normalize_currency(currency: str) -> str:
    code = _clean("currency", currency).lower()
    if len(code) != 3:
        raise ValueError("currency must be a 3-letter ISO code")
    return code


@dataclass(frozen=True)
class BalanceTransaction:
    """One row from the balance transaction ledger.

    ``amount`` is the gross movement in cents and may be negative (refunds,
    most adjustments). ``fee`` is the Stripe fee withheld on that movement, in
    cents, and is always reported as a non-negative magnitude by the API.
    """

    txn_id: str
    type: str
    amount: int
    fee: int
    currency: str
    source_id: str = ""
    description: str = ""

    def __post_init__(self) -> None:
        txn_id = _clean("txn_id", self.txn_id)
        txn_type = _clean("type", self.type)
        if txn_type not in SUPPORTED_TYPES:
            raise ValueError(f"unsupported balance transaction type: {txn_type}")
        if not isinstance(self.amount, int) or isinstance(self.amount, bool):
            raise ValueError("amount must be an integer number of cents")
        if not isinstance(self.fee, int) or isinstance(self.fee, bool):
            raise ValueError("fee must be an integer number of cents")
        if self.fee < 0:
            raise ValueError("fee is a magnitude and must be non-negative")
        currency = _normalize_currency(self.currency)
        object.__setattr__(self, "txn_id", txn_id)
        object.__setattr__(self, "type", txn_type)
        object.__setattr__(self, "currency", currency)
        object.__setattr__(self, "source_id", str(self.source_id).strip())
        object.__setattr__(self, "description", str(self.description).strip())

    @property
    def gross_cents(self) -> int:
        """Signed gross movement before fees, exactly as the ledger reports it."""
        return self.amount

    @property
    def fee_cents(self) -> int:
        """Fee magnitude withheld on this transaction (non-negative)."""
        return self.fee

    def is_credit(self) -> bool:
        return self.type in CREDIT_TYPES

    def is_reduction(self) -> bool:
        """Refunds and negative adjustments pull money back out of the payout."""
        return self.amount < 0


@dataclass
class PayoutBatch:
    """A payout and the balance transactions Stripe bundled into it.

    ``declared_amount_cents`` is the amount Stripe says it sent to the bank for
    this payout. The export's job is to reproduce that number from the line
    items so finance can tie the report back to the bank statement.
    """

    payout_id: str
    currency: str
    declared_amount_cents: int
    arrival_unix: int
    transactions: list[BalanceTransaction] = field(default_factory=list)

    def __post_init__(self) -> None:
        self.payout_id = _clean("payout_id", self.payout_id)
        self.currency = _normalize_currency(self.currency)
        if not isinstance(self.declared_amount_cents, int) or isinstance(
            self.declared_amount_cents, bool
        ):
            raise ValueError("declared_amount_cents must be an integer")
        for txn in self.transactions:
            if not isinstance(txn, BalanceTransaction):
                raise ValueError("transactions must be BalanceTransaction rows")
            if txn.currency != self.currency:
                raise ValueError(
                    "transaction currency does not match payout currency"
                )

    def add(self, txn: BalanceTransaction) -> None:
        if not isinstance(txn, BalanceTransaction):
            raise ValueError("transactions must be BalanceTransaction rows")
        if txn.currency != self.currency:
            raise ValueError("transaction currency does not match payout currency")
        self.transactions.append(txn)

    def line_count(self) -> int:
        return len(self.transactions)


def build_transaction(
    *,
    txn_id: str,
    type: str,
    amount: int,
    fee: int = 0,
    currency: str = "usd",
    source_id: str = "",
    description: str = "",
) -> BalanceTransaction:
    return BalanceTransaction(
        txn_id=txn_id,
        type=type,
        amount=amount,
        fee=fee,
        currency=currency,
        source_id=source_id,
        description=description,
    )


def build_payout(
    *,
    payout_id: str,
    currency: str = "usd",
    declared_amount_cents: int,
    arrival_unix: int = 1_700_000_000,
    transactions: list[BalanceTransaction] | None = None,
) -> PayoutBatch:
    return PayoutBatch(
        payout_id=payout_id,
        currency=currency,
        declared_amount_cents=declared_amount_cents,
        arrival_unix=arrival_unix,
        transactions=list(transactions or []),
    )


def money_label(cents: int, currency: str) -> str:
    sign = "-" if cents < 0 else ""
    major = abs(cents) / 100
    return f"{sign}{major:.2f} {currency.upper()}"

