from __future__ import annotations

"""Gross / fee / net arithmetic for a single balance transaction.

The accounting identity the export depends on is simple:

    net = gross - fee

where ``gross`` is the signed movement on the ledger and ``fee`` is the
non-negative fee magnitude withheld. A payout's total is the sum of the *net*
amounts of every balance transaction Stripe bundled into it. Refunds and
negative adjustments carry a negative gross, so their net is negative and they
pull the payout down.
"""

from balance_transaction_models import BalanceTransaction


def gross_for(txn: BalanceTransaction) -> int:
    """Signed gross movement in cents, straight from the ledger."""
    return txn.gross_cents


def fee_for(txn: BalanceTransaction) -> int:
    """Fee withheld on the transaction, in cents.

    The ledger stores fees as a non-negative magnitude. Reconciliation reports
    show the fee as the amount taken away from gross, so it is returned with a
    sign that reflects its effect on net.
    """
    return -txn.fee_cents


def net_for(txn: BalanceTransaction) -> int:
    """Net contribution of one transaction to the payout, in cents.

    Net is gross minus the fee withheld. Because :func:`fee_for` already encodes
    the fee as a reduction, the net combines the two signed pieces.
    """
    return gross_for(txn) + fee_for(txn) - txn.fee_cents


def signed_components(txn: BalanceTransaction) -> dict[str, int]:
    """Break a transaction into the three columns finance reconciles on."""
    return {
        "gross_cents": gross_for(txn),
        "fee_cents": fee_for(txn),
        "net_cents": net_for(txn),
    }


def sum_gross(transactions: list[BalanceTransaction]) -> int:
    return sum(gross_for(txn) for txn in transactions)


def sum_fees(transactions: list[BalanceTransaction]) -> int:
    """Total fee effect across transactions (negative reduces the payout)."""
    return sum(fee_for(txn) for txn in transactions)


def sum_net(transactions: list[BalanceTransaction]) -> int:
    """Total net across transactions. This is what a payout total should equal."""
    return sum(net_for(txn) for txn in transactions)


def fee_magnitude_total(transactions: list[BalanceTransaction]) -> int:
    """Absolute fee withheld across transactions, always non-negative."""
    return sum(txn.fee_cents for txn in transactions)


def split_by_direction(
    transactions: list[BalanceTransaction],
) -> dict[str, list[BalanceTransaction]]:
    """Partition into money-in credits and money-out reductions.

    Refunds and negative adjustments land in ``reductions``. Everything that
    adds to the payout lands in ``credits``.
    """
    credits: list[BalanceTransaction] = []
    reductions: list[BalanceTransaction] = []
    for txn in transactions:
        if txn.is_reduction():
            reductions.append(txn)
        else:
            credits.append(txn)
    return {"credits": credits, "reductions": reductions}


def reconciliation_columns(transactions: list[BalanceTransaction]) -> dict[str, int]:
    """Roll-up of the three reconciliation columns for a set of transactions."""
    return {
        "gross_cents": sum_gross(transactions),
        "fee_cents": sum_fees(transactions),
        "net_cents": sum_net(transactions),
        "fee_magnitude_cents": fee_magnitude_total(transactions),
    }


def assert_identity_holds(txn: BalanceTransaction) -> bool:
    """Sanity check that net ties back to gross and fee for one transaction."""
    components = signed_components(txn)
    expected_net = components["gross_cents"] - txn.fee_cents
    return components["net_cents"] == expected_net

