from __future__ import annotations

"""Reconciliation pass over a batch of payouts for the finance close.

Finance runs this at month end. It builds a report per payout, checks each one
ties back to the amount Stripe declared, and flags any that do not so someone
can chase the difference before the books close.
"""

from balance_transaction_models import PayoutBatch
from fee_net_math import fee_magnitude_total
from payout_report_builder import (
    build_payout_report,
    payout_total_from_line_items,
)


def reconcile_payout(payout: PayoutBatch) -> dict[str, object]:
    report = build_payout_report(payout)
    rebuilt_total = payout_total_from_line_items(report)
    return {
        "payout_id": report["payout_id"],
        "currency": report["currency"],
        "payout_total_cents": report["payout_total_cents"],
        "line_item_total_cents": rebuilt_total,
        "declared_amount_cents": report["declared_amount_cents"],
        "ties_out": report["ties_out"],
        "difference_cents": report["difference_cents"],
        "line_item_total_matches": rebuilt_total == report["payout_total_cents"],
        "fee_withheld_cents": fee_magnitude_total(payout.transactions),
        "report": report,
    }


class PayoutReconciliation:
    """Stateful pass that remembers every payout it has reconciled."""

    def __init__(self) -> None:
        self._results: list[dict[str, object]] = []

    def add(self, payout: PayoutBatch) -> dict[str, object]:
        outcome = reconcile_payout(payout)
        self._results.append(outcome)
        return outcome

    def results(self) -> list[dict[str, object]]:
        return list(self._results)

    def mismatches(self) -> list[dict[str, object]]:
        return [r for r in self._results if not r["ties_out"]]

    def all_tie_out(self) -> bool:
        return all(r["ties_out"] for r in self._results)

    def totals_by_currency(self) -> dict[str, int]:
        totals: dict[str, int] = {}
        for result in self._results:
            currency = str(result["currency"])
            totals[currency] = totals.get(currency, 0) + int(
                result["payout_total_cents"]
            )
        return totals


def reconcile_batch(payouts: list[PayoutBatch]) -> dict[str, object]:
    pass_ = PayoutReconciliation()
    for payout in payouts:
        pass_.add(payout)
    results = pass_.results()
    mismatches = pass_.mismatches()
    return {
        "payout_count": len(results),
        "tie_out_count": len(results) - len(mismatches),
        "mismatch_count": len(mismatches),
        "all_tie_out": pass_.all_tie_out(),
        "totals_by_currency": pass_.totals_by_currency(),
        "results": results,
        "mismatches": mismatches,
    }


def close_status(batch_summary: dict[str, object]) -> str:
    if batch_summary["payout_count"] == 0:
        return "nothing_to_reconcile"
    if batch_summary["mismatch_count"]:
        return "needs_finance_review"
    return "ready_to_close"


def first_mismatch(summary: dict[str, object]) -> dict[str, object] | None:
    for result in summary["results"]:
        if not result["ties_out"]:
            return result
    return None

